INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('815a16b08172b5797ec0da76ce1da27f', 'JEEMains', '12', 'Mathematics', 'math_12_jm_application_of_integrals', 'Application of Integrals', 'Area using horizontal strips', '["math_12_jm_definite_integration"]', '["area under curve","horizontal strip integration","definite integral","sign change in integrand","piecewise integration"]', 1, 0, '[]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 6, 0.0, 'The area bounded by the curve $x = y^2 - 4y$, the $y$-axis, and the lines $y = 1$ and $y = 5$ is calculated using horizontal strips. What is the area (in square units)?', '[]', '16', 'We use horizontal strips to compute the area between $x = y^2 - 4y$ and the $y$-axis from $y = 1$ to $y = 5$. The area is given by $\int_{1}^{5} |x|\,dy = \int_{1}^{5} |y^2 - 4y|\,dy$. The expression $y^2 - 4y = y(y - 4)$ changes sign at $y = 4$. So we split the integral: $\int_1^4 -(y^2 - 4y)\,dy + \int_4^5 (y^2 - 4y)\,dy$. Evaluating gives $\left[-\frac{y^3}{3} + 2y^2\right]_1^4 + \left[\frac{y^3}{3} - 2y^2\right]_4^5 = \frac{25}{3} + \frac{23}{3} = 16$.', '["Step 1: Express area using horizontal strips: $\\int_{y=1}^{5} |x(y)|\\,dy$", "Step 2: Identify where $x = y^2 - 4y$ is negative: $y \\in [1,4)$", "Step 3: Split integral at $y = 4$", "Step 4: Compute $\\int_1^4 -(y^2 - 4y)\\,dy$", "Step 5: Compute $\\int_4^5 (y^2 - 4y)\\,dy$", "Step 6: Add results: $\\frac{25}{3} + \\frac{23}{3} = 16$"]', '\int_a^b f(y)\,dy', 'math.calculus.area_sign_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:51.058Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('815b3b9f6b4bea65f76c61bf70fd8b9e', 'JEEMains', '12', 'Mathematics', 'math_12_jm_probability', 'Probability', 'Random Variables and Their Distributions', '[]', '["Expected value","Discrete random variable","Probability distribution","Linear expectation","Algebraic solving"]', 0, 0, '[]', 'MCQ', NULL, 0, 2200, 'JEE_MAINS_MEDIUM', 4, -1.0, 'A discrete random variable \(X\) takes values \(1,2,3\) with probabilities \(p,\;2p,\;1-3p\) respectively. Find the value of \(p\) for which the expected value \(E[X]=2\).', '["0.25", "0.20", "0.33", "0.50"]', '0.25', 'Compute \(E[X]=1\cdot p+2\cdot 2p+3\cdot(1-3p)=3-4p\). Setting this equal to 2 gives \(4p=1\) so \(p=0.25\).', '["Step 1: Write the expression for \\(E[X]\\) using the given probabilities.", "Step 2: Substitute the probabilities and simplify the algebraic expression.", "Step 3: Equate the simplified expression to 2 and solve for \\(p\\).", "Step 4: Verify that the obtained \\(p\\) yields valid probabilities (all non‑negative)."]', 'For a discrete variable, \(E[X]=\sum x_i P(X=x_i)\).', 'math.probability.prob_sum_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:58:05.065Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('8162db4f2ed778748df43b2124f22142', 'JEEMains', '12', 'Physics', 'phy_12_jm_electrostatics', 'Electrostatics', 'Electric flux', '[]', '["Gauss''s law","electric flux","field lines","point charge","spherical symmetry"]', 0, 0, '[]', 'MCQ', NULL, 0, 2120, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A point charge of $+5\,\mu\text{C}$ is placed at the centre of a spherical Gaussian surface of radius $10\,\text{cm}$. What is the electric flux $\Phi_E$ through the surface?', '["5.6\\times10^{5}\\ \\text{N·m}^2\\!\\!/\\!\\text{C}", "2.8\\times10^{5}\\ \\text{N·m}^2\\!\\!/\\!\\text{C}", "1.13\\times10^{6}\\ \\text{N·m}^2\\!\\!/\\!\\text{C}", "0 \\ \\text{N·m}^2\\!\\!/\\!\\text{C}"]', '5.6\times10^{5}\ \text{N·m}^2\!\!/\!\text{C}', 'Gauss''s law gives $\Phi_E = Q_{\text{enc}}/\varepsilon_0$. Substituting $Q=5\times10^{-6}\,\text{C}$ and $\varepsilon_0=8.854\times10^{-12}\,\text{F·m}^{-1}$ yields $\Phi_E \approx 5.6\times10^{5}\,\text{N·m}^2\!\!/\!\text{C}$. The other options arise from common factor‑mistakes or neglecting the flux altogether.', '["Step 1: Write Gauss''s law $\\Phi_E = Q_{\\text{enc}}/\\varepsilon_0$.", "Step 2: Insert $Q = 5\\times10^{-6}\\,\\text{C}$ and $\\varepsilon_0 = 8.854\\times10^{-12}\\,\\text{F·m}^{-1}$.", "Step 3: Perform the division to obtain $\\Phi_E \\approx 5.6\\times10^{5}\\,\\text{N·m}^2\\!\\!/\\!\\text{C}$."]', '$\Phi_E = \dfrac{Q_{\text{enc}}}{\varepsilon_0}$', 'physics.electrostatics.gauss_law_sign', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:11:06.471Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('81635146f5c9bfd3593437c9274786ac', 'JEEMains', '12', 'Mathematics', 'math_12_jm_differential_equations', 'Differential Equations', 'Order and Degree', '[]', '["order of ODE","degree of ODE","polynomial condition","higher derivative","non‑polynomial term"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Determine the order and degree of the differential equation $$\frac{d^{2}y}{dx^{2}} + \left(\frac{dy}{dx}\right)^{1/2} = \sin x.$$', '["Order 1, Degree 2", "Order 2, Degree not defined", "Order 2, Degree 1", "Order 1, Degree not defined"]', 'Order 2, Degree not defined', 'The highest derivative present is $\frac{d^{2}y}{dx^{2}}$, so the order is 2. The term $(dy/dx)^{1/2}$ is a fractional power, making the equation non‑polynomial in the derivative; therefore the degree is not defined.', '["Step 1: Identify the highest order derivative – here it is $d^{2}y/dx^{2}$.", "Step 2: Check if the equation is polynomial in the derivatives after removing radicals and fractions.", "Step 3: Since $(dy/dx)^{1/2}$ is a radical, the degree is not defined."]', 'Order = highest derivative; Degree = power of highest derivative after clearing radicals', 'math.diff_eq.order_degree', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:44:54.248Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('8166f2694c799dd92f04d0de6ffa17a4', 'JEEMains', '11', 'Physics', 'phy_11_jm_projectile', 'Motion in a Plane', 'Projectile Motion', '[]', '["projectile motion","time of flight","launch angle","initial velocity","vertical component"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 4, -1.0, 'A projectile is launched from ground level at an angle of $30^{\circ}$ to the horizontal. Its total time of flight is 4 s. What is the magnitude of its initial speed? (Take $g = 9.8\,\text{m/s}^{2}$)', '["20 m/s", "30 m/s", "39.2 m/s", "50 m/s"]', '39.2 m/s', 'Time of flight $t = \frac{2u\sin\theta}{g}$ ⇒ $u = \frac{gt}{2\sin\theta} = \frac{9.8\times4}{2\times0.5}=39.2\,\text{m/s}$.', '["Step 1: Use the time‑of‑flight formula for projectile motion: $t = \\frac{2u\\sin\\theta}{g}$.", "Step 2: Substitute $t = 4\\,\\text{s}$, $\\theta = 30^{\\circ}$ (so $\\sin30^{\\circ}=0.5$), and $g = 9.8\\,\\text{m/s}^{2}$.", "Step 3: Rearrange to solve for $u$: $u = \\frac{gt}{2\\sin\\theta}$.", "Step 4: Compute $u = \\frac{9.8\\times4}{2\\times0.5}=39.2\\,\\text{m/s}$."]', 't = \frac{2u\sin\theta}{g}', 'physics.jm.projectile.time_of_flight', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:51:49.801Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('8167a174496c0dd7f60402c997cdb870', 'Board', '10', 'Science', 'bio_10_board_mendelian', 'Mendelian genetics', 'Monohybrid cross', '[]', '["dominant recessive","phenotypic ratio","heterozygous","tall trait"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 3, 0.0, 'When a heterozygous tall plant (Tt) is crossed with a short plant (tt), what is the expected phenotypic ratio of tall to short offspring?', '["3:1", "1:1", "2:1", "1:2"]', '3:1', 'A Punnett square for Tt × tt gives genotypes TT, Tt, Tt, tt. The three tall genotypes (TT, Tt, Tt) correspond to a 3:1 phenotypic ratio of tall to short.', '["Step 1: Set up the Punnett square for Tt × tt.", "Step 2: List the resulting genotypes: TT, Tt, Tt, tt.", "Step 3: Convert genotypes to phenotypes, obtaining 3 tall : 1 short."]', '', 'biology.genetics.monohybrid', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:15:06.692Z', -1);
